package mx.com.mesaregia.logistica.application.service.impl; import mx.com.mesaregia.logistica.exception.ConflictException; final class ServiceSupport {private ServiceSupport(){} static void version(Long actual,Long enviada){if(enviada==null||!enviada.equals(actual))throw new ConflictException("Versión desactualizada; recargue el registro");} static String texto(String s){return s==null?null:s.trim();}}
